-- Infinite loop example 1: variable jumps over the target value
x ← 0
REPEAT UNTIL(x = 5)
{
   x ← x + 2    -- x goes 0, 2, 4, 6, 8...
}                -- x jumps FROM 4 TO 6, NEVER equals exactly 5
                 -- condition never becomes true → INFINITE LOOP

-- Infinite loop example 2: loop variable never updated
count ← 0
REPEAT UNTIL(count = 5)
{
   DISPLAY count  -- count is always 0
}                  -- count never changes → INFINITE LOOP

-- Infinite loop example 3: condition can never be true
y ← 10
REPEAT UNTIL(y < 0)
{
   y ← y + 1    -- y only increases, can never go below 0
}                -- INFINITE LOOP
